const { jsPDF } = window.jspdf;
  var font =
    "";
  var callAddFont = function () {
    this.addFileToVFS("NotoSansJP-VariableFont_wght-normal.ttf", font);
    this.addFont(
      "NotoSansJP-VariableFont_wght-normal.ttf",
      "NotoSansJP",
      "normal"
    );
  };
  jsPDF.API.events.push(["addFonts", callAddFont]);
